package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamTheatreDramaBank1 {
    private const val T = "නූර්ති, නාඩගම් සහ සිංහල නාට්‍ය සංගීතය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රී ලංකාවේ ප්‍රථම වෘත්තීය වේදිකා නාට්‍ය සම්ප්‍රදාය ලෙස සැලකෙන්නේ කුමක්ද?", "නාඩගම් කලාව", "නූර්ති කලාව", "සොකරි කලාව", "කෝලම් කලාව", "පෘතුගීසි හා දකුණු ඉන්දීය ආභාසයෙන් නාඩගම් කලාව බිහිවිය."),
        q("නාඩගම් කලාවේ පුරෝගාමියා ලෙස හඳුන්වනු ලබන ශ්‍රී ලාංකිකයා කවුද?", "පිලිප්පු සිංඤෝ", "ජෝන් ද සිල්වා", "සී. දොන් බස්තියන්", "මහාචාර්ය සරච්චන්ද්‍ර", "මුල් යුගයේ සිංහල නාඩගම් රචනා කිරීමේ පුරෝගාමියා පිලිප්පු සිංඤෝය."),
        q("නාඩගම් වේදිකාවේ නාට්‍යය ආරම්භයේදී චරිත හඳුන්වා දීම සඳහා ගී ගයන්නේ කවුද?", "පොතේගුරු", "මුදලිතුමා", "සෙල්ලම් ලමයා", "විදූෂකයා", "නාඩගම් රංග පීඨයේ කතාව මෙහෙයවමින් සබය අමතන්නේ පොතේගුරුය."),
        q("නාඩගම් කලාවට දකුණු ඉන්දියාවෙන් ලැබුණු සම්ප්‍රදායික ආභාසය කුමක්ද?", "තෙරුක්කූත්තු නාට්‍ය කලාව", "කථකලි නර්තන කලාව", "පාර්සි නාට්‍ය කලාව", "භරත නාට්‍යම් කලාව", "දකුණු ඉන්දීය තෙරුක්කූත්තු සහ තමිල් කූත්තු ආභාසය නාඩගමට ලැබුණි."),
        q("නාඩගම් සංගීතයේ ප්‍රධාන වශයෙන්ම භාවිත වන අවනද්ධ වාද්‍ය භාණ්ඩය කුමක්ද?", "මද්දලය", "තබ්ලාව", "ගැටබෙරය", "තම්මැට්ටම", "නාඩගම් ගායනා සඳහා තාලය සපයන මූලික භාණ්ඩය මද්දලයයි."),
        q("නාඩගමක ස්වර හා රාග පසුබිම කවර සංගීත සම්ප්‍රදායට වඩාත් සමීපද?", "කර්ණාටක සංගීතයට", "හින්දුස්ථානි සංගීතයට", "බටහිර සම්භාව්‍ය සංගීතයට", "පර්සියානු සංගීතයට", "නාඩගම් තනු බොහොමයක් දකුණු ඉන්දීය කර්ණාටක ආභාසය ලබා ඇත."),
        q("පිලිප්පු සිංඤෝ විසින් රචිත සුප්‍රසිද්ධ නාඩගම් කෘතිය කුමක්ද?", "ඇහැලේපොළ නාඩගම", "සිරිසඟබෝ නාට්‍යය", "මනමේ නාට්‍යය", "රොලීනා නාට්‍යය", "ඇහැලේපොළ නාඩගම පිලිප්පු සිංඤෝගේ ප්‍රකට නාඩගම් නිර්මාණයකි."),
        q("නාඩගම් රංගනයේදී වේදිකාවට ප්‍රවේශ වන චරිතයකට විශේෂයෙන් ගායනා කරන පද්‍ය කොටස කුමක්ද?", "විරිදු හා කවි", "ලාවණි ගීත", "ගසල් ගීත", "කීර්තන ගීත", "චරිත පිවිසුමේදී මද්දල නාදය අනුව ඉන්නිස හා කවි ගායනා කෙරේ."),
        q("නාඩගම් වේදිකාවේ පොතේගුරු විසින් ගායනා කරනු ලබන පළමු ප්‍රශංසා ගීතය කුමක්ද?", "ඉන්නිස ගීතය", "දොහරා ගීතය", "තානා ගීතය", "ඛ්‍යාල් ගීතය", "නාඩගම ආරම්භයේ දෙවිවරුන් හා රැස්වූ පිරිස නමස්කාර කරන ඉන්නිස ගැයේ."),
        q("චාල්ස් සිල්වා ගුණසිංහ ගුරුන්නාන්සේ ප්‍රකට වන්නේ කුමන සංගීත ක්ෂේත්‍රය සඳහාද?", "නාඩගම් ගායනා සම්ප්‍රදාය", "නූර්ති හාමෝනියම් වාදනය", "ග්‍රැමෆෝන් සරල ගීත", "බටහිර ඔපෙරා ගායනය", "සිංහල නාඩගම් ගී පරපුර රැකගත් ප්‍රවීණයෙකු ලෙස එතුමා ප්‍රසිද්ධය."),
        q("නාඩගම් කලාවේ ප්‍රධාන පසුබිම් වාද්‍ය භාණ්ඩ යුගලය වන්නේ මද්දලය සහ කුමක්ද?", "තාලම්පට", "වයලීනය", "බන්සූරිය", "සිතාරය", "නාඩගම් රංගනයේදී මද්දලය සමඟ තාලම්පට හා හොරණෑව භාවිත කෙරේ."),
        q("සිංහල නාඩගම් පොත් රචනා කිරීමේදී පද්‍ය හා ගීත අතර භාවිත කළ බස කුමක්ද?", "දෙමළ හුරුව ඇති සිංහල", "පාලි හා සංස්කෘත මිශ්‍ර බස", "නූතන කටවහර පමණක්", "ඉංග්‍රීසි මිශ්‍රිත බස", "මුල් නාඩගම්වල දෙමළ වචන මිශ්‍ර උත්තරීතර කාව්‍යමය බසක් තිබුණි."),
        q("'සින්දු' යන නාමය සිංහල ගීත කලාවට මුලින්ම බහුලව එක්වූයේ කුමන නාට්‍ය අංගය හරහාද?", "නාඩගම් සම්ප්‍රදාය", "සොකරි නාටකය", "කෝලම් නැටුම", "සඳකිඳුරු නැටුම", "දකුණු ඉන්දීය චින්දු තනු ආශ්‍රිතව නාඩගම් සින්දු සිංහලයට එක්විය."),
        q("ශ්‍රී ලංකාවේ නූර්ති නාට්‍ය කලාවේ ආරම්භකයා ලෙස සැලකෙන්නේ කවුද?", "සී. දොන් බස්තියන්", "ජෝන් ද සිල්වා", "චාල්ස් ඩයස්", "විශ්වනාත් ලෞජි", "1877 දී රොලීනා නාට්‍යයෙන් සී. දොන් බස්තියන් නූර්ති කලාව ඇරඹීය."),
        q("සිංහල නූර්ති නාට්‍ය සඳහා සෘජු බලපෑමක් සිදු කළ විදේශීය නාට්‍ය සම්ප්‍රදාය කුමක්ද?", "ඉන්දීය පාර්සි නාට්‍ය කලාව", "චීන පීකිං ඔපෙරා කලාව", "ජපන් නෝ නාට්‍ය කලාව", "ග්‍රීක ශෝකාන්ත නාට්‍ය කලාව", "බොම්බායේ පාර්සි නාට්‍ය කණ්ඩායම්වල පැමිණීම නූර්ති උපතට හේතු විය."),
        q("සී. දොන් බස්තියන් විසින් රචිත ප්‍රථම සිංහල නූර්ති නාට්‍යය ලෙස සැලකෙන්නේ කුමක්ද?", "රොලීනා", "සිරිසඟබෝ", "වෙස්සන්තර", "ශ්‍රී වික්‍රම", "1877 දී වේදිකාගත වූ රොලීනා ප්‍රථම නූර්ති නාට්‍යයයි."),
        q("නූර්ති නාට්‍ය කලාව දේශීය ජාතිකාභිමානී මාවතකට යොමු කළ විශිෂ්ට නාට්‍යකරුවා කවුද?", "නීතිඥ ජෝන් ද සිල්වා", "පිලිප්පු සිංඤෝ", "එදිරිවීර සරච්චන්ද්‍ර", "දයානන්ද ගුණවර්ධන", "බෞද්ධ හා ජාතික ඉතිහාස කතා ඇසුරෙන් ජෝන් ද සිල්වා නූර්ති නිර්මාණය කළේය."),
        q("ජෝන් ද සිල්වාගේ නූර්ති නාට්‍ය සඳහා හින්දුස්ථානි රාගධාරී තනු නිර්මාණය කළ ඉන්දීය සංගීතඥයා කවුද?", "විශ්වනාත් ලෞජි", "අමීර් ඛුස්රෝ", "විෂ්ණු නාරායන් භාත්ඛණ්ඩේ", "උස්තාද් අල්ලා රක්ඛා", "බොම්බායෙන් ගෙන්වාගත් විශ්වනාත් ලෞජි සුප්‍රකට නූර්ති තනු නිර්මාණය කළේය."),
        q("'දන්නෝ බුදුන්ගේ ශ්‍රී ධර්මස්කන්ධා' යන ගීතය ඇතුළත් වන්නේ කුමන නූර්ති නාට්‍යයේද?", "සිරිසඟබෝ නාට්‍යයේ", "ශ්‍රී වික්‍රම නාට්‍යයේ", "වෙස්සන්තර නාට්‍යයේ", "රත්නාවලී නාට්‍යයේ", "ජෝන් ද සිල්වාගේ සිරිසඟබෝ නූර්තියේ මෙම අමරණීය ගීතය ඇතුළත් වේ."),
        q("'දන්නෝ බුදුන්ගේ' ගීතයේ තනුව කවර ජනප්‍රිය සංගීත ප්‍රභවයක ආභාසයෙන් නිමවූවක්ද?", "ප්‍රංශ ජාතික ගීය හා භෛරවී ආභාසය", "තමිල් කීර්තනා රාග ආභාසය", "දේශීය ගොයම් කවි නාද මාලාව", "ජපන් පෙන්ටටොනික් ස්වර මාලාව", "විශ්වනාත් ලෞජි විසින් ජාතික ගී හුරුව හා උත්තර භාරතීය ශෛලිය මුසු කරන ලදී."),
        q("'අඹ දඹ නාරන් කෙසෙල් දෙල්' යන ගීතය ඇතුළත් නූර්ති නාට්‍යය කුමක්ද?", "වෙස්සන්තර", "සිරිසඟබෝ", "ශකුන්තලා", "දුටුගැමුණු", "වෙස්සන්තර නූර්තියේ වනාන්තරයේ පලතුරු වර්ණනා කරමින් මෙම ගීතය ගැයේ."),
        q("නූර්ති සංගීතයේ ප්‍රධාන වශයෙන් භාවිත වූ තාල වාද්‍ය භාණ්ඩ දෙක කුමක්ද?", "හාමෝනියමය සහ තබ්ලාව", "මද්දලය සහ තාලම්පට", "ගැටබෙරය සහ හොරණෑව", "පියානෝව සහ ඩ්‍රම්ස්", "හින්දුස්ථානි ආභාසය නිසා නූර්තිවලට තබ්ලාව සහ සර්පිනාව එක්විය."),
        q("සිංහල නූර්ති යුගයේදී 'සර්පිනාව' යනුවෙන් හඳුන්වනු ලැබූ වාද්‍ය භාණ්ඩය කුමක්ද?", "හාමෝනියමය", "සිතාරය", "වයලීනය", "ක්ලැරිනට් නළාව", "පෙට්ටි හාමෝනියමය ජන වහරේ සර්පිනාව ලෙස හැඳින්විණි."),
        q("චාල්ස් ඩයස් මහතා විසින් රචිත ප්‍රසිද්ධ නූර්ති නාට්‍යයක් වන්නේ කුමක්ද?", "පද්මාවතී", "රොලීනා", "පරාභව", "සඳකිඳුරු", "ජෝන් ද සිල්වාගෙන් පසු චාල්ස් ඩයස් පද්මාවතී හා විධුර වැනි නූර්ති ලීවේය."),
        q("නූර්ති සංගීතය මගින් ශ්‍රී ලංකාවට මුලින්ම ප්‍රචලිත වූ ඉන්දියානු සංගීත සම්ප්‍රදාය කුමක්ද?", "උත්තර භාරතීය හින්දුස්ථානි සංගීතය", "දක්ෂිණ භාරතීය කර්ණාටක සංගීතය", "බටහිර ජෑස් සංගීතය", "චීන පෞරාණික සංගීතය", "විශ්වනාත් ලෞජි හා පාර්සි නාට්‍ය හරහා හින්දුස්ථානි රාග මෙරට පැතිරුණි."),
        q("වේදිකාවේ පින්තාරු කළ තිර රෙදි යොදාගනිමින් දර්ශන වෙනස් කිරීම ප්‍රචලිත වූයේ කුමන නාට්‍ය අංගයේද?", "නූර්ති නාට්‍යයේ", "නාඩගම් නාට්‍යයේ", "සොකරි නාට්‍යයේ", "කෝලම් නාට්‍යයේ", "පාර්සි නාට්‍ය ආභාසයෙන් නූර්ති වේදිකාවට ප්‍රොසීනියම් වේදිකාව හා තිර රෙදි ආවේය."),
        q("'ශ්‍රී වික්‍රම' නූර්ති නාට්‍යය රචනා කළ නාට්‍යකරුවා කවුද?", "ජෝන් ද සිල්වා", "සී. දොන් බස්තියන්", "පිලිප්පු සිංඤෝ", "ජී. ඩී. එල්. පෙරේරා", "අවසන් සිංහල රජුගේ චරිතය අළලා ජෝන් ද සිල්වා ශ්‍රී වික්‍රම රචනා කළේය."),
        q("'ප්‍රේමයෙන් මන රංජිත වේ' ගීතය ඇතුළත් වන්නේ කවර සම්භාව්‍ය නාට්‍යයකද?", "මනමේ නාට්‍යයේ", "සිරිසඟබෝ නාට්‍යයේ", "සිංහබාහු නාට්‍යයේ", "නරිබෑණා නාට්‍යයේ", "එදිරිවීර සරච්චන්ද්‍රයන්ගේ 1956 මනමේ නාට්‍යයේ මෙම ප්‍රකට ගීතය ඇතුළත් වේ."),
        q("නූතන සිංහල නාට්‍ය කලාවේ හැරවුම් ලක්ෂ්‍යය ලෙස සැලකෙන 'මනමේ' නාට්‍යය වේදිකාගත වූයේ කවර වර්ෂයේද?", "1956", "1948", "1961", "1939", "1956 නොවැම්බර් 03 දින මහාචාර්ය එදිරිවීර සරච්චන්ද්‍රයන් මනමේ වේදිකාගත කළේය."),
        q("මනමේ නාට්‍යයේ ආකෘතිය සහ සංගීත රටාව සඳහා පදනම් කරගත් දේශීය නාට්‍ය සම්ප්‍රදාය කුමක්ද?", "නාඩගම් සම්ප්‍රදාය", "නූර්ති සම්ප්‍රදාය", "බටහිර ඔපෙරාව", "ටීටර් නාට්‍ය කලාව", "වැලිගම චාල්ස් සිල්වා ගුණසිංහ ගුරුන්නාන්සේගේ නාඩගම් ආකෘතිය මනමේට යොදාගැණිනි."),
        q("මනමේ නාට්‍යයේ සංගීත නිර්මාණය සඳහා සරච්චන්ද්‍රයන්ට සහාය වූ ප්‍රධාන නාඩගම් ගුරුවරයා කවුද?", "චාල්ස් සිල්වා ගුණසිංහ ගුරුන්නාන්සේ", "ඩබ්ලිව්. ඩී. අමරදේව", "විශ්වනාත් ලෞජි", "ආනන්ද සමරකෝන්", "නාඩගම් තාල හා ගායන ශෛලීන් ලබාදීමට චාල්ස් ගුණසිංහ ගුරුන්නාන්සේ දායක විය."),
        q("මනමේ නාට්‍යයේ වැදි රජුගේ චරිතය හඳුන්වා දෙන ගායනා ඛණ්ඩය සමඟ ප්‍රධානව වාදනය වන බෙරය කුමක්ද?", "මද්දලය", "උඩැක්කිය", "තබ්ලාව", "බොංගෝ බෙරය", "මනමේ නාට්‍යය නාඩගම් ශෛලිය ගත් බැවින් මද්දලය හා හොරණෑව ප්‍රධාන වේ."),
        q("'සිංහබාහු' වේදිකා නාට්‍යය මුල් වරට වේදිකාගත කරන ලද්දේ කුමන වර්ෂයේදීද?", "1961", "1956", "1968", "1974", "සරච්චන්ද්‍රයන්ගේ සිංහබාහු නාට්‍යය 1961 දී පේරාදෙණියේදී ප්‍රථම වරට රඟදැක්විණි."),
        q("'ගල් ලෙන බිඳලා ලෙන් දොර ඇරලා' ගීතය ඇතුළත් සුප්‍රසිද්ධ නාට්‍යය කුමක්ද?", "සිංහබාහු", "මනමේ", "පබාවතී", "ලෝමහංස", "සිංහබාහු නාට්‍යයේ සිංහයා ගුහාව බිඳ පැමිණි අවස්ථාවේ ගැයෙන ප්‍රකට ගීතයයි."),
        q("සිංහබාහු නාට්‍යයේ සංගීත සංයෝජනයෙහිදී නාඩගම් තනු සමඟ මුසු කරන ලද ශාස්ත්‍රීය සම්ප්‍රදාය කුමක්ද?", "උත්තර භාරතීය හා දේශීය ජන නාද", "චීන පෙන්ටටොනික් තනු", "බටහිර සිම්ෆනි වාදන", "ලතින් ඇමරිකානු රිද්ම", "නාඩගම් නාද මාලා මෙන්ම රාගධාරී හා ජන නාද ආභාසය සිංහබාහු තුළ දක්නට ලැබේ."),
        q("'කුණ්ඩලකේශී' වැනි ශෛලිගත නාට්‍යවල සංගීතය සඳහා යොදාගත් ප්‍රධාන ශෛලිය කුමක්ද?", "ශෛලිගත ගීතමය නාට්‍ය රීතිය", "ස්වභාවික දෙබස් නාට්‍ය රීතිය", "බටහිර ඔපෙරා රීතිය", "ටීටර් හාස්‍ය රීතිය", "සිංහල ශෛලිගත නාට්‍යවල සංවාද පවා ගායනාමය ස්වරූපයෙන් ඉදිරිපත් වේ."),
        q("දයානන්ද ගුණවර්ධනයන්ගේ 'නරිබෑණා' නාට්‍යයේ සංගීතය සඳහා බහුලව යොදාගත් මූලාශ්‍රය කුමක්ද?", "සිංහල ජන කවි හා ජන ගී නාද මාලා", "බටහිර පියානෝ ස්වර රචනා", "පාර්සි නූර්ති තනු රටා", "තමිල් තෙරුක්කූත්තු තාල", "දේශීය ජන ගී සහ ජන කතා ඇසුරින් නරිබෑණා හි ගීත නිර්මාණය විය."),
        q("'කුමටද සොබනියෙ කඳුළු සලන්නේ' ගීතය ඇතුළත් වන්නේ කුමන නාට්‍යයේද?", "නරිබෑණා නාට්‍යයේ", "ජසයා සහ ලෙන්චිනා නාට්‍යයේ", "හුණුවටයේ කතාවේ", "රතු හැට්ටකාරී නාට්‍යයේ", "දයානන්ද ගුණවර්ධනයන්ගේ නරිබෑණා නාට්‍යයේ ගැමි නාද රටාවෙන් යුත් ගීතයකි."),
        q("හෙන්රි ජයසේනයන්ගේ 'හුණුවටයේ කතාව' නාට්‍යයේ සංගීතය නිර්මාණය කළ ප්‍රවීණයා කවුද?", "ෂෙල්ටන් ප්‍රේමරත්න", "ප්‍රේමසිරි කේමදාස", "ඩබ්ලිව්. ඩී. අමරදේව", "රෝහණ වීරසිංහ", "හුණුවටයේ කතාවේ සංගීතය ෂෙල්ටන් ප්‍රේමරත්නයන්ගේ විශිෂ්ට නිර්මාණයකි."),
        q("'යුද්ධයටත් ඇවිදින් සිදු වූ දේ' වැනි ගීත ඇතුළත් හුණුවටයේ කතාව කුමන නාට්‍ය රීතියක් ආභාසය කළේද?", "බ්‍රෙෂ්ටියානු එපික් නාට්‍ය රීතිය", "සාම්ප්‍රදායික කෝලම් රීතිය", "පුරාණ සංස්කෘත නාට්‍ය රීතිය", "පාර්සි නූර්ති රීතිය", "බර්ටෝල්ට් බ්‍රෙෂ්ට්ගේ වීරකාව්‍ය නාට්‍ය රීතිය අනුව ප්‍රේක්ෂකයාට ආමන්ත්‍රණය කෙරේ."),
        q("ලුසියන් බුලත්සිංහලගේ 'රතු හැට්ටකාරී' නාට්‍යයේ අපූරු සංගීත නිර්මාණය කළේ කවුද?", "ඔස්ටින් මුණසිංහ", "සරත් දසනායක", "සෝමදාස ඇල්විටිගල", "රෝහණ බැද්දගේ", "ඔස්ටින් මුණසිංහයන් විසින් රතු හැට්ටකාරී නාට්‍යයේ සංගීතය නිර්මාණය කළේය."),
        q("'තාරාවෝ ඉගිලෙති' නාට්‍යයේ ගීතවලට සංගීතය සැපයූ ප්‍රකට සංගීතවේදියා කවුද?", "ගුණදාස කපුගේ", "ප්‍රේමසිරි කේමදාස", "වික්ටර් රත්නායක", "සනත් නන්දසිරි", "ලුසියන් බුලත්සිංහලගේ තාරාවෝ ඉගිලෙති නාට්‍යයට ගුණදාස කපුගේ සංගීතය සැපයීය."),
        q("සිංහල ග්‍රැමෆෝන් ගීත යුගයේ ආරම්භය සිදුවූයේ කවර සියවසේ මුල් භාගයේද?", "20 වන සියවසේ මුල් භාගයේ", "18 වන සියවසේ අග භාගයේ", "19 වන සියවසේ මුල් භාගයේ", "21 වන සියවසේ මුල් භාගයේ", "1903 පමණ සිට ලංකාවේ නූර්ති හා සරල ගී ග්‍රැමෆෝන් තැටිවල පටිගත විය."),
        q("මුල්ම සිංහල ග්‍රැමෆෝන් තැටිවල පටිගත වූයේ ප්‍රධාන වශයෙන් කුමන ගීත විශේෂයද?", "නූර්ති ගීත", "නූතන රැප් ගීත", "පැල් කවි පමණක්", "කැරොල් ගීත පමණක්", "මුල් යුගයේ ග්‍රැමෆෝන් තැටිවල ජනප්‍රිය නූර්ති ගීත පටිගත කෙරිණි."),
        q("ලංකාවේ ග්‍රැමෆෝන් ගීත යුගයේ ප්‍රසිද්ධ ගායන ශිල්පියෙකු හා නළුවෙකු වූයේ කවුද?", "එච්. ඩබ්ලිව්. රූපසිංහ මාස්ටර්", "පිලිප්පු සිංඤෝ", "ජෝතිපාල මහතා", "මොහිදීන් බෙග්", "රූපසිංහ මාස්ටර් ග්‍රැමෆෝන් යුගයේ රාගධාරී ගී ගැයූ ප්‍රමුඛ ගායකයෙකි."),
        q("ග්‍රැමෆෝන් යුගයේ සංගීතය සඳහා ඉන්දියාවේ සිට පැමිණි හෝ ඊට දායක වූ ප්‍රසිද්ධ ලංකාවේ තැටි සමාගම කුමක්ද?", "එච්. එම්. වී. (HMV)", "සෝනි මියුසික්", "වෝනර් බ්‍රදර්ස්", "සරසවි රෙකෝඩ්ස්", "His Master's Voice (HMV) සහ Columbia තැටි සමාගම් ගීත පටිගත කළේය."),
        q("සිංහල ග්‍රැමෆෝන් ගීත කලාව ස්වාධීන දේශීය ගීත සම්ප්‍රදායකට ගෙන ආ විශිෂ්ටයා කවුද?", "ආනන්ද සමරකෝන්", "ජෝන් ද සිල්වා", "පිලිප්පු සිංඤෝ", "රවි ශංකර්", "හින්දි තනු කොපි කිරීමෙන් මිදී දේශීය තනු නිර්මාණය ආනන්ද සමරකෝන් ඇරඹීය."),
        q("'එන්ඩද මැණිකේ' සහ 'පොඩි මල් එතනෝ' වැනි ගීත අයත් වන්නේ කුමන යුගයටද?", "ග්‍රැමෆෝන් සරල ගී යුගයට", "නාඩගම් යුගයට", "පැරණි කෝලම් යුගයට", "ටෙලිනාට්‍ය තේමා ගී යුගයට", "1940 දශකයේ ආනන්ද සමරකෝන්ගේ ස්වතන්ත්‍ර ග්‍රැමෆෝන් ගීත මේ ගණයට වැටේ."),
        q("සොකරි ගැමි නාටකයේ ප්‍රධාන වශයෙන් නිරූපණය කෙරෙන කතා පුවත හා බැඳුණු දෙවියා කවුද?", "පත්තිනි දේවිය හා ගුරු හාමි", "විෂ්ණු දෙවියන්", "ශිව දෙවියන්", "සමන් දෙවියන්", "පත්තිනි දේවියගේ ආශිර්වාදය පතා ගුරුහාමි හා සොකරි කතාව රඟදැක්වේ."),
        q("සොකරි ගැමි නාටකය බහුල වශයෙන් රඟදක්වනු ලබන්නේ ශ්‍රී ලංකාවේ කුමන ප්‍රදේශවලද?", "උඩරට හා සත් කෝරළ ප්‍රදේශවල", "දකුණු මුහුදුබඩ තීරයේ", "යාපනය අර්ධද්වීපයේ", "මන්නාරම් වෙරළ තීරයේ", "උඩරට, වන්නිය හා හත්කෝරළයේ ගැමි කමත්වල සොකරි රඟදක්වයි."),
        q("සොකරි නාටකයේ සංගීතය සඳහා යොදාගන්නා ප්‍රධාන වාද්‍ය භාණ්ඩය කුමක්ද?", "ගැටබෙරය හෝ උඩැක්කිය", "තබ්ලාව හා සිතාරය", "පියානෝව හා වයලීනය", "මද්දලය හා ඩෝල්කිය", "ගැමි කමතේදී ගැටබෙරය හා හොරණෑව සොකරි සඳහා භාවිත කෙරේ."),
        q("කෝලම් ගැමි නාට්‍ය සම්ප්‍රදාය ශ්‍රී ලංකාවේ කුමන ප්‍රදේශයට ආවේණික වූවක්ද?", "පහතරට මුහුදුබඩ ප්‍රදේශයට", "මහනුවර කඳුකර ප්‍රදේශයට", "අනුරාධපුර රජරට ප්‍රදේශයට", "බදුල්ල ඌව ප්‍රදේශයට", "අම්බලන්ගොඩ, බෙන්තර ආදී පහතරට ප්‍රදේශවල කෝලම් නාට්‍යය ප්‍රචලිතය."),
        q("කෝලම් නාට්‍යයේ චරිත නිරූපණය සඳහා විශේෂයෙන් යොදාගන්නා කලාත්මක අංගය කුමක්ද?", "වෙස්මුහුණු පැළඳීම", "මුහුණේ කළු තීන්ත ගෑම", "රූකඩ නූල් භාවිතය", "සෙවණැලි තිර භාවිතය", "කැටයම් කළ වර්ණවත් ලී වෙස්මුහුණු පැළඳ කෝලම් චරිත රඟපායි."),
        q("කෝලම් නාට්‍යයේ ගීත හා නැටුම් සඳහා ප්‍රධානව වාදනය කරන බෙර වර්ගය කුමක්ද?", "යක්බෙරය (පහතරට බෙරය)", "ගැටබෙරය (උඩරට බෙරය)", "මද්දලය", "තම්මැට්ටම", "පහතරට සම්ප්‍රදායේ ප්‍රධාන බෙරය වන යක්බෙරය හා හොරණෑව කෝලම් සඳහා යොදාගනී."),
        q("දයානන්ද ගුණවර්ධනයන්ගේ 'මධුර ජවනිකා' නාට්‍යයේ අන්තර්ගත වන්නේ කුමන ආකාරයේ සංගීතයක්ද?", "ශ්‍රී ලාංකේය සංගීත විකාශන අවධි", "බටහිර සම්භාව්‍ය සංගීතය පමණක්", "කර්ණාටක කීර්තනා පමණක්", "අරාබි ජන ගීත පමණක්", "නාඩගම්, නූර්ති හා ග්‍රැමෆෝන් යුගවල සංගීත ඉතිහාසය මධුර ජවනිකාහි ඉදිරිපත් වේ."),
        q("දේශීය ගැමි නාටක වන 'සඳකිඳුරු' ජාතක නාටකයේ සංගීතය කවර අංගයකට අයත් වේද?", "දේශීය නාට්‍යමය ගැමි කවි සම්ප්‍රදායට", "පාර්සි නූර්ති සම්ප්‍රදායට", "ග්‍රැමෆෝන් සරල ගී සම්ප්‍රදායට", "කැරොල් ගී සම්ප්‍රදායට", "සඳකිඳුරු කින්නර රංගනයේදී දේශීය කවි තනු හා ජන නාද ගැයේ."),
        q("මනමේ නාට්‍යයේ එන 'ලප නොමවන් සඳ සේ' යන ගීතය ගායනා කරන්නේ කවුරුන් විසින්ද?", "මනමේ කුමරිය", "මනමේ කුමාරයා", "වැදි රජු", "පොතේගුරු", "වැදි රජු කෙරෙහි ආලය උපන් මනමේ කුමරිය මෙම ගීතය ගයයි."),
        q("ප්‍රේමසිරි කේමදාසයන් සංගීතවත් කළ විශිෂ්ට වේදිකා නාට්‍යයක් වන්නේ කුමක්ද?", "මාරාසාද් හෝ සෙක්කුව", "රොලීනා", "සිරිසඟබෝ", "ඇහැලේපොළ නාඩගම", "ආචාර්ය ප්‍රේමසිරි කේමදාස සෙක්කුව, මාරාසාද් වැනි නාට්‍ය සඳහා නව්‍ය සංගීතය සැපයීය."),
        q("නාඩගම් රංගනයේදී බොහෝ විට පිරිමි චරිත මෙන්ම කාන්තා චරිත ද රඟපෑවේ කවුරුන් විසින්ද?", "පිරිමි නළුවන් විසින්", "කාන්තා නිළියන් විසින්", "කුඩා දරුවන් විසින්", "වෙස්මුහුණු නැට්ටුවන් විසින්", "පැරණි නාඩගම් වේදිකාවේ කාන්තා චරිත පවා රඟපෑවේ පිරිමි නළුවන්ය."),
        q("නූර්ති නාට්‍ය සංගීතයේ ගීත රචනා බොහෝ විට කවර ස්වභාවයකින් යුක්ත වීද?", "රාගධාරී තනුවට අනුව වචන යෙදීම", "නිසඳැස් කවි ලෙස ලිවීම", "හයිකු කවි ආකෘතියෙන් ලිවීම", "ඉංග්‍රීසි පද මිශ්‍ර කර ලිවීම", "මෙට්‍රොපොලිටන් හා පාර්සි හින්දුස්ථානි තනුවලට ගැළපෙන පරිදි සිංහල පද යෙදීය."),
        q("ජෝන් ද සිල්වාගේ 'ශකුන්තලා' නූර්තියට පදනම් වූයේ කුමන පැරණි සාහිත්‍ය කෘතියද?", "කාලිදාසගේ අභිඥාන ශාකුන්තලය", "වල්මිකීගේ රාමායණය", "පන්සිය පනස් ජාතක පොත", "මහාවංශය", "මහා කවි කාලිදාසගේ සංස්කෘත නාට්‍යය ඇසුරෙන් ශකුන්තලා නූර්තිය නිර්මාණය විය."),
        q("නාඩගම් වේදිකාවේ ප්‍රධාන පසුබිම් නළුවා ලෙස හාස්‍ය රසය මවන චරිතය කුමක්ද?", "සෙල්ලම් ලමයා හා කෝනංගියා", "පොතේගුරු", "මහ රජතුමා", "දේවදූතයා", "නාඩගම් රංගනයේදී ප්‍රේක්ෂකයා පිනවන විකට චරිත කෝනංගි සහ සෙල්ලම් ලමයාය."),
        q("'මුහුදු පුත්තු' වැනි ගුණසේන ගලප්පත්තිගේ නාට්‍ය සඳහා සංගීතය සැපයූ විශිෂ්ටයා කවුද?", "සෝමදාස ඇල්විටිගල", "විශ්වනාත් ලෞජි", "මොහොමඩ් ගවුස්", "චාල්ස් සිල්වා ගුණසිංහ", "ධීවර ජීවිතය පසුබිම් කරගත් මුහුදු පුත්තු නාට්‍යයට සෝමදාස ඇල්විටිගල සංගීතය සැපයීය."),
        q("'සඳ කිඳුරු' දා කව ඇසුරින් සැකසුණු දේශීය ගැමි රංගනය හඳුන්වන්නේ කුමන නමකින්ද?", "සඳකිඳුරු නාඩගම / කවි නැටුම", "සොකරි නාටකය", "වැදි රංගනය", "කෝලම් රංගනය", "සඳකිඳුරු ජාතකය නාට්‍යානුසාරයෙන් කවි ගායනයෙන් හා නැටුමෙන් ඉදිරිපත් කෙරේ."),
        q("ශ්‍රී ලංකාවේ 'ගීත නාටක' (ඔපෙරා හුරුව ඇති) සම්ප්‍රදාය දියුණු කිරීමට මුල් වූ සංගීතඥයෙකු කවුද?", "ආචාර්ය ප්‍රේමසිරි කේමදාස", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "මුහන්දිරම් සිල්වා", "කේමදාසයන්ගේ මානසවිල, දොරමඩල, අග්නි වැනි නිර්මාණ සිංහල ඔපෙරා කලාවට අයත් වේ."),
        q("සරච්චන්ද්‍රයන්ගේ 'පබාවතී' නාට්‍යයේ සංගීතය සඳහා උපයෝගී කරගත් ආභාසය කුමක්ද?", "උත්තර භාරතීය හා කවි නාද රටා", "බටහිර ජෑස් හා බ්ලූස් නාද", "චීන ජන නාද", "අප්‍රිකානු බෙර තාල", "දේශීය කවි සහ ශාස්ත්‍රීය රාග ආභාසය පබාවතී නාට්‍යයේ ගීතවල දක්නට ලැබේ."),
        q("නාඩගම් වේදිකාව ගොඩනඟන ලද සාම්ප්‍රදායික හැඩය කුමක්ද?", "වෘත්තාකාර හෝ අර්ධ කවාකාර කරළිය", "පින්තාරු තිර සහිත හතරැස් වේදිකාව", "බහු මහල් විදුලි වේදිකාව", "ජලය මත තැනූ පාවෙන වේදිකාව", "ප්‍රේක්ෂකයන් තුන් පැත්තකින් වටකර සිටින පස් කන්දක කරළිය තැනිණි."),
        q("නූර්ති නාට්‍ය වේදිකාගත කිරීමේදී මුල් යුගයේ බහුලව යොදාගත් ආලෝකකරණ ක්‍රමය කුමක්ද?", "පෙට්‍රෝමැක්ස් හෝ ගෑස් ලාම්පු", "පරිගණකගත LED පුවරු", "ලේසර් ආලෝක කිරණ", "පොල්තෙල් පන්දම් පමණක්", "නූර්ති ශාලාවල තිර අදින වේදිකා ආලෝකවත් කිරීමට ගෑස් හා පෙට්‍රෝමැක්ස් ලාම්පු භාවිත විය."),
        q("'වටපුළුවේ රාජසිංහ' හෝ 'රාමායණය' වැනි නූර්තිවල ගීත තනු බොහෝමයක් කවර මූලයකින් ලැබුණිද?", "ඉන්දියානු උර්දු හා හින්දි රංග ගී", "ස්කොට්ලන්ත බෑග්පයිප් තනු", "පෘතුගීසි කපිරිඤ්ඤා තනු", "කාපිරි ගෝත්‍රික ගීත", "බොම්බායේ පාර්සි නාට්‍යවල ජනප්‍රිය උර්දු හා හින්දි තනු මෙරට නූර්තිවලට එක්විය."),
        q("'මගෙ මද්‍රි නම් බිසෝ' යන නූර්ති ගීතය අයත් වන්නේ කුමන ජනප්‍රිය නාට්‍යයටද?", "වෙස්සන්තර නාට්‍යයට", "සිරිසඟබෝ නාට්‍යයට", "රොලීනා නාට්‍යයට", "පද්මාවතී නාට්‍යයට", "වෙස්සන්තර රජු තම දේවිය අමතා ගයන මෙම ගීතය නූර්ති යුගයේ අතිශය ජනප්‍රිය විය."),
        q("නූතන වේදිකා නාට්‍යයක් වන 'සිංහබාහු' නාට්‍යයේ සුප්පා දේවියගේ දුක ප්‍රකාශ වන ගීත කවර ශෛලියක් ගනීද?", "ශෝකී කරුණ රසැති ගායන ශෛලිය", "උපහාසාත්මක හාස්‍ය රස ශෛලිය", "වේගවත් නර්තන බයිලා ශෛලිය", "සන්නාහ වීර රස මාර්ච් ශෛලිය", "සුප්පා දේවියගේ ගායනා තුළ කරුණ රසය ඉස්මතු වන ලයාන්විත නාද රටා පවතී."),
        q("මනමේ නාට්‍යයේ වැදි රජුගේ සිංදු සඳහා යොදාගත් තාල හා ලය කවර ස්වභාවයක් ගනීද?", "වේගවත් හා ගාම්භීර වීර රස ලය", "ඉතා සෙමින් ගැයෙන විලම්බ ලය", "අවසර රහිත නිදහස් ගායනය", "බටහිර වොල්ට්ස් තාලය", "වැදි රජුගේ ජවය හා ශූරත්වය පෙන්වීමට මද්දල තාල හා වීර රස ලය යොදාගැනේ."),
        q("නාඩගමක ආරම්භයේදී සියලු දෙනා එක්ව ගායනා කරන පූජා හා මංගල ගීතය කෙසේ හැඳින්වේද?", "මංගල අෂ්ටක හා පූර්ව රංග ගී", "අවසන් මංගල සින්දුව", "මධ්‍යම අතුරු කතාව", "විකට ගීත කණ්ඩය", "පූර්ව රංගයේදී දේව ආශිර්වාදය පතා පොතේගුරු හා අත්වැල් ගායකයෝ මංගල ගී ගයති."),
        q("දයානන්ද ගුණවර්ධනයන්ගේ 'ගජමන් පුවත' නාට්‍යයේ ගීත සඳහා භාවිත කළ ප්‍රධාන කාව්‍ය සම්ප්‍රදාය කුමක්ද?", "මාතර යුගයේ කවි හා සිලෝ රටා", "සංස්කෘත ශ්ලෝක රටා පමණක්", "නූතන ඉංග්‍රීසි සොනට් ආකෘතිය", "උර්දු ගසල් ආකෘතිය", "ගජමන් නෝනාගේ ජීවිත කතාව ඇසුරින් මාතර කවි හා වන්නම් තාල මෙහි යොදාගැනිණි."),
        q("'කැලණි පාලම' නාට්‍යයට සංගීතය සැපයූ ප්‍රවීණ සංගීත අධ්‍යක්ෂවරයා කවුද?", "රෝහණ වීරසිංහ", "ෂෙල්ටන් ප්‍රේමරත්න", "විශ්වනාත් ලෞජි", "ආනන්ද සමරකෝන්", "ආර්. ආර්. සමරකෝන්ගේ කැලණි පාලම නාට්‍යයට රෝහණ වීරසිංහයන් සංගීතය සැපයීය."),
        q("'සිකුරාදා රෑ' වැනි සරල නාට්‍ය සංගීතයෙන් ඔබ්බට ගොස් මුළුමනින්ම ගීතයෙන් රඟදැක්වෙන නාට්‍යය කුමක්ද?", "ගීත නාටකය (ඔපෙරා)", "ගද්‍ය සංවාද නාට්‍යය", "මූක නාට්‍යය (Mime)", "ඒකපුද්ගල ප්‍රහසනය", "සංවාද නොමැතිව ගායනයෙන් හා සංගීතයෙන් පමණක් දිවෙන නාට්‍ය ගීත නාටක හෙවත් ඔපෙරා වේ."),
        q("ශ්‍රී ලංකාවේ ප්‍රථම සිංහල ගීත නාටකය හෙවත් ඔපෙරාව ලෙස සැලකෙන 'විදුර' හෝ මුල් යුගයේ නාට්‍ය නිර්මාණය කළේ කවුද?", "ඩබ්ලිව්. බී. මකුලොළුව (දෙපානෝ)", "ජෝන් ද සිල්වා", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "මකුලොළුවන්ගේ 'දෙපානෝ' දේශීය ගීත නාටක සම්ප්‍රදායේ සුවිශේෂී කෘතියකි."),
        q("සිංහල නාට්‍ය වේදිකාවට දේශීය ජන ගී ආකෘතිය ප්‍රායෝගිකව හඳුන්වා දුන් 'මහගෙදර' හෝ 'දෙපානෝ' නිර්මාතෘ කවුද?", "ඩබ්ලිව්. බී. මකුලොළුව", "මොහොමඩ් ගවුස්", "බී. එස්. පෙරේරා", "එච්. ආර්. ජෝතිපාල", "ඩබ්ලිව්. බී. මකුලොළුව දේශීය ජන ගී පදනම් කරගත් ගීත නාටක රචනා කළේය."),
        q("මහචාර්ය සරච්චන්ද්‍රයන් 'ප්‍රේමතෝ ජායතී සෝකෝ' නාට්‍යයට භාවිත කළ සංගීත රටාව කුමක්ද?", "සංස්කෘත හා ශාස්ත්‍රීය රාග ආභාසය", "පෘතුගීසි බයිලා නාද රටාව", "රොක් සංගීත රටාව", "පහතරට තොවිල් නාද රටාව", "උද්දාල බ්‍රාහ්මණ කතාව ඇසුරින් සැකසුණු මෙහි රාගධාරී හා ශාස්ත්‍රීය ගායන රීති යොදාගැණිනි."),
        q("නාඩගම් ගීත ගායනා කිරීමේදී ගායකයා හා මද්දල වාදකයා අතර පවතින සබඳතාව කුමක්ද?", "තාල පද හා සින්දු එක්ව මෙහෙයවීම", "වෙන වෙනම තනිව වාදනය කිරීම", "ගායනය අවසන් වූ පසු බෙර ගැසීම", "තාලයකින් තොරව නිදහසේ ගැයීම", "ගායකයා සින්දුවේ මුල් පද ගයන අතර මද්දලය ඊට අනුරූප තාල පද ගසයි."),
        q("නාඩගම් රංග පීඨයේදී චරිත වේදිකාවට එන අතරතුර නටන වෘත්තාකාර ගමන් රටාව හඳුන්වන්නේ කෙසේද?", "වට්ටම් ගමන හෙවත් මණ්ඩල පැදීම", "නූර්ති පෙළපාලිය", "පිරුවට ගමන", "සරඹ ගමන", "වේදිකාව වටා තාලයට පියවර තබමින් නළුවෝ චරිතයට පිවිසෙති."),
        q("සිංහල නූර්ති ගීත පොත් මුද්‍රණය කර විකිණීමෙන් එදා ප්‍රේක්ෂකයාට ලැබුණු ප්‍රයෝජනය කුමක්ද?", "නාට්‍යයේ ගීත පද හා රාග නාම දැනගැනීම", "නළුවන්ගේ ඡායාරූප බැලීම පමණක්", "නාට්‍ය ශාලාවේ මාර්ග සිතියම ලැබීම", "වාද්‍ය භාණ්ඩ මිලදී ගැනීම", "නූර්ති ගී පොත්වල ගී පද මෙන්ම ඒවා ගැයෙන රාග හා තාල නාමද සටහන් කර තිබුණි."),
        q("'සුරතලියේ කුමටද කෝප වීලා' යන ජනප්‍රිය සින්දුව අයත් වන්නේ කුමන නාට්‍ය සම්ප්‍රදායටද?", "නාඩගම් සම්ප්‍රදායට", "ග්‍රැමෆෝන් සරල ගීතයට", "බටහිර ඔපෙරාවට", "චිත්‍රපට සංගීතයට", "මෙය නාඩගම් රඟමඬලින් ජනප්‍රිය වූ සින්දු පෙළකි."),
        q("නාඩගම් කලාවේ මුලින්ම ලියවුණු කිතුනු ආගමික නාඩගමක් වන්නේ කුමක්ද?", "රජ තුන් කට්ටුව හා සුසෑනා නාඩගම", "සිරිසඟබෝ නාඩගම", "මනමේ නාඩගම", "නරිබෑණා නාඩගම", "හලාවත හා මීගමුව ප්‍රදේශවල රජ තුන් කට්ටුව වැනි කිතුනු නාඩගම් බිහිවිය."),
        q("ගැමි කෝලම් නාට්‍යය ආරම්භයේදී සියලු දෙනාගේ ආරක්ෂාව පතා පළමුව වේදිකාවට එන චරිතය කවුද?", "සබාපති හා අණබෙරකරු", "සිංහ රාජයා", "වැදි රජු", "නාග කන්‍යාව", "අණබෙරකරු නොහොත් පනික්කිරාළ පැමිණ නාට්‍යය ඇරඹෙන බව ප්‍රකාශ කරයි."),
        q("කෝලම් නාට්‍යයේදී බෙර වාදනයෙන් හා ගායනයෙන් චරිත හඳුන්වා දෙනු ලබන්නේ කවුරුන් විසින්ද?", "සබාපති හා බෙර වාදකයා", "නිළියන් පිරිස", "වෙස්මුහුණු කැටයම්කරු", "ගමේ විදානේ", "කෝලම් මඩුවේ සබාපති හෙවත් කාරියකරවන රාළ කවි කියමින් චරිත කැඳවයි."),
        q("නාඩගම් යුගය හා නූර්ති යුගය අතර ප්‍රධානතම සංගීත වෙනස කුමක්ද?", "කර්ණාටක ආභාසයේ සිට හින්දුස්ථානි ආභාසයට මාරුවීම", "බටහිර සංගීතයේ සිට අරාබි සංගීතයට මාරුවීම", "වාද්‍ය භාණ්ඩ සම්පූර්ණයෙන් ඉවත් කිරීම", "ගීත ගායනය වෙනුවට දෙබස් පමණක් යෙදීම", "නාඩගමේ දකුණු ඉන්දීය මද්දල සංගීතය වෙනුවට නූර්තියේ උතුරු ඉන්දීය තබ්ලා සර්පිනා එක්විය."),
        q("ජෝන් ද සිල්වාගේ 'රාමායණය' නූර්තියේ ගීතවලට තනු සැපයූයේ කවුරුන් විසින්ද?", "විශ්වනාත් ලෞජි", "පිලිප්පු සිංඤෝ", "ඩබ්ලිව්. ඩී. අමරදේව", "ප්‍රේමසිරි කේමදාස", "ජෝන් ද සිල්වාගේ ප්‍රධාන නූර්ති කිහිපයකම සංගීත අධ්‍යක්ෂණය විශ්වනාත් ලෞජි සිදු කළේය."),
        q("නූර්ති නාට්‍ය කලාව කොළඹ 'ටවර් හෝල්' රඟහල කේන්ද්‍ර කරගෙන දියුණු වූයේ කවර දශකයේද?", "1910 - 1920 දශකවල", "1970 - 1980 දශකවල", "1820 - 1830 දශකවල", "1990 - 2000 දශකවල", "1911 දී ටවර් හෝල් විවෘත කිරීමත් සමඟ නූර්ති කලාවේ ස්වර්ණමය යුගය ඇතිවිය."),
        q("ටවර් හෝල් රඟහල විවෘත කරන ලද්දේ කවර වර්ෂයේදීද?", "1911", "1948", "1877", "1956", "1911 දෙසැම්බර් මාසයේදී ටවර් හෝල් රඟහල නූර්ති නාට්‍ය සඳහා විවෘත කෙරිණි."),
        q("ටවර් හෝල් නූර්ති යුගයේ ජනප්‍රිය වූ ප්‍රධාන නළු නිළියන් ගැන සඳහන් වන්නේ කුමන නාට්‍ය පරපුරේද?", "ඇනී බොතේජු හා රොමුලස් ද සිල්වා පරපුර", "මනමේ කණ්ඩායම් පරපුර", "ගමේ සොකරි පරපුර", "ටෙලිනාට්‍ය නළු පරපුර", "ඇනී බොතේජු, සුසිලා ජයසිංහ, රොමුලස් ද සිල්වා වැනි ශිල්පීන් ටවර් හෝල් යුගය බැබළවූහ."),
        q("නූර්ති යුගයේ සිට චිත්‍රපට යුගයට පිවිසෙන අතරතුර බිහිවූ 'මිනර්වා' නාට්‍ය කණ්ඩායම මෙහෙයවූයේ කවුද?", "බී. ඒ. ඩබ්ලිව්. ජයමාන්න", "ජෝන් ද සිල්වා", "එදිරිවීර සරච්චන්ද්‍ර", "හෙන්රි ජයසේන", "මීගමුව මිනර්වා නාට්‍ය කණ්ඩායමේ 'කඩවුණු පොරොන්දුව' පසුව ප්‍රථම සිංහල චිත්‍රපටය විය."),
        q("1947 තිරගත වූ ප්‍රථම සිංහල කථානාද චිත්‍රපටය වන 'කඩවුණු පොරොන්දුව' සඳහා සංගීතය සැපයූයේ කවුද?", "ආර්. නාරායන අයියර්", "ප්‍රේමසිරි කේමදාස", "ඩබ්ලිව්. ඩී. අමරදේව", "රෝහණ වීරසිංහ", "දකුණු ඉන්දියාවේ රූගත කළ කඩවුණු පොරොන්දුවේ සංගීතය ආර්. නාරායන අයියර් සැපයීය."),
        q("වේදිකා නාට්‍යයක් නරඹන ප්‍රේක්ෂකයාට කතාවේ හැඟීම් තීව්‍ර කිරීමට සංගීතය උපකාරී වන අයුරු කුමක්ද?", "පසුබිම් නාද හා ගායනා මගින් රසය ඉස්මතු කිරීම", "නළුවන්ගේ දෙබස් සම්පූර්ණයෙන් වසා දැමීම", "අනවශ්‍ය ඝෝෂාවක් ඇති කිරීම", "විවේක කාලයේ පමණක් වාදනය කිරීම", "සුදුසු ස්ථානවල පසුබිම් සංගීතය හා ගීත යෙදීමෙන් නාට්‍යයේ රසභාව තීව්‍ර කෙරේ."),
        q("ජන ගී ආභාසයෙන් නාට්‍ය නිර්මාණය කළ ආචාර්ය රෝහණ බැද්දගේ සම්බන්ධ වූ ප්‍රකට නාට්‍යයක් කුමක්ද?", "සඳ කිඳුරු හෝ බලල් පැටව්", "මැක්බත්", "හැම්ලට්", "රොලීනා", "දේශීය ජන සංගීත අංග රංග කලාව සමඟ එක්කිරීමට රෝහණ බැද්දගේ කටයුතු කළේය."),
        q("රූකඩ නාට්‍ය කලාව ශ්‍රී ලංකාවේ බහුලව ප්‍රචලිත වී ඇති පැරණි ප්‍රදේශය කුමක්ද?", "අම්බලන්ගොඩ ප්‍රදේශය", "නුවරඑළිය ප්‍රදේශය", "යාපනය ප්‍රදේශය", "පොළොන්නරුව ප්‍රදේශය", "දකුණු ලක අම්බලන්ගොඩ නූල් රූකඩ කලාවේ මධ්‍යස්ථානයයි."),
        q("අම්බලන්ගොඩ නූල් රූකඩ නාට්‍ය කලාවේ සංගීතය සඳහා බලපෑම් කළ ප්‍රධාන සම්ප්‍රදාය කුමක්ද?", "නාඩගම් ගායනා හා බෙර සම්ප්‍රදාය", "බටහිර ඔපෙරා සම්ප්‍රදාය", "ගසල් ගායනා සම්ප්‍රදාය", "ජපන් නෝ සම්ප්‍රදාය", "රූකඩ නැටවීමේදී පැරණි නාඩගම් සින්දු හා මද්දල හෝ ඩෝල්කි වාදනය යොදාගනී."),
        q("නාඩගම් හා නූර්ති යන දෙවර්ගයේම ගීතවල පොදුවේ දැකිය හැකි ප්‍රධාන ලක්ෂණය කුමක්ද?", "රංග ශෛලිය හා බැඳුණු පද්‍ය ගායනාමය බව", "දෙබස් කථනය පමණක් තිබීම", "වාද්‍ය භාණ්ඩ කිසිවක් නොමැති වීම", "එක් ගීතයක් පමණක් තිබීම", "මෙම නාට්‍ය දෙවර්ගයෙහිම කතාව ඉදිරියට ගෙනයන්නේ ගීත ගායනය මගිනි."),
        q("'මනමේ' නාට්‍යයේ ආරම්භයේදී සභාව අමතා කතාව ගෙනහැර දක්වන ප්‍රධාන චරිතය කවුද?", "පොතේගුරු", "වැදි රජු", "දිසාපාමොක් ඇදුරු", "සෙබළා", "සාම්ප්‍රදායික නාඩගම් රීතිය අනුව මනමේ නාට්‍යයේද කතාව මෙහෙයවන්නේ පොතේගුරුය."),
        q("'ලෝමහංස' හා 'වෙල්ලවැහුම්' වැනි ශෛලිගත නාට්‍ය නිර්මාණය කළ ප්‍රවීණ නාට්‍යවේදියා කවුද?", "මහාචාර්ය එදිරිවීර සරච්චන්ද්‍ර", "ජෝන් ද සිල්වා", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "මනමේ හා සිංහබාහු මෙන්ම ලෝමහංස, වෙල්ලවැහුම් ආදිය සරච්චන්ද්‍රයන්ගේ නිර්මාණයන්ය."),
        q("සිංහල නාට්‍ය සංගීතයේදී 'තාලම්පට' නැමැති ඝන වාද්‍ය භාණ්ඩයේ ප්‍රධාන කාර්යය කුමක්ද?", "ගායනයට හා නැටුමට තාලයේ ඒකාග්‍රතාව රැකදීම", "රාගයේ ආරෝහණ අවරෝහණ වාදනය කිරීම", "සුසිර නාදයක් පිට කිරීම", "පසුබිම් මන්ද්‍ර නාදය රැකීම", "තාලම්පට මගින් සම්පූර්ණ වාදක කණ්ඩායමටම තාලයේ මාත්‍රා ඒකාබද්ධ කෙරේ."),
        q("'ගුරු තරුව' වේදිකා නාට්‍යයට සංගීතය නිර්මාණය කළ ප්‍රවීණයා කවුද?", "ප්‍රේමසිරි කේමදාස", "විශ්වනාත් ලෞජි", "ෂෙල්ටන් ප්‍රේමරත්න", "මොහොමඩ් ගවුස්", "ජයලත් මනෝරත්නයන්ගේ ගුරු තරුව නාට්‍යයට කේමදාසයන් සංගීතය සැපයීය."),
        q("සිංහල චිත්‍රපට සංගීතයට දේශීය හා ශාස්ත්‍රීය මුහුණුවරක් එක් කළ මුල් පෙළේ සංගීතවේදියෙකු කවුද?", "පණ්ඩිත් ඩබ්ලිව්. ඩී. අමරදේව", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "රොමුලස් ද සිල්වා", "ගම්පෙරළිය, රන්සළු, දෙලොවක් අතර වැනි චිත්‍රපටවලට අමරදේවයන් විශිෂ්ට සංගීතය සැපයීය.")
    )
}
